    JPanel titlePanel = new JPanel(new BorderLayout());
    titlePanel.setBorder(new EmptyBorder(0, 0, 10, 0));

    JLabel title = new JLabel(ProjectXericConfig.NAME);
    title.setForeground(Color.WHITE);
